def text(key, lang):
    """Return a required translation and fail the build when a locale is missing."""
    values = TEXT[key]
    if len(values) != len(LANGS):
        raise ValueError(f"Translation key {key!r} has {len(values)} values")
    return values[LANGS.index(lang)]
